macro_rules! AsInitialized {
    () => {
        # [doc = " The byte ranges initialized in `T` are also initialized in the referent of a"] # [doc = " `Ptr<T>`."] # [doc = ""] # [doc = " Formally: uninitialized bytes may only be present in `Ptr<T>`'s referent"] # [doc = " where they are guaranteed to be present in `T`. This is a dynamic property:"] # [doc = " if, at a particular byte offset, a valid enum discriminant is set, the"] # [doc = " subsequent bytes may only have uninitialized bytes as specified by the"] # [doc = " corresponding enum."] # [doc = ""] # [doc = " Formally, given `len = size_of_val_raw(ptr)`, at every byte offset, `b`, in"] # [doc = " the range `[0, len)`:"] # [doc = " - If, in any instance `t: T` of length `len`, the byte at offset `b` in `t`"] # [doc = "   is initialized, then the byte at offset `b` within `*ptr` must be"] # [doc = "   initialized."] # [doc = " - Let `c` be the contents of the byte range `[0, b)` in `*ptr`. Let `S` be"] # [doc = "   the subset of valid instances of `T` of length `len` which contain `c` in"] # [doc = "   the offset range `[0, b)`. If, in any instance of `t: T` in `S`, the byte"] # [doc = "   at offset `b` in `t` is initialized, then the byte at offset `b` in `*ptr`"] # [doc = "   must be initialized."] # [doc = ""] # [doc = "   Pragmatically, this means that if `*ptr` is guaranteed to contain an enum"] # [doc = "   type at a particular offset, and the enum discriminant stored in `*ptr`"] # [doc = "   corresponds to a valid variant of that enum type, then it is guaranteed"] # [doc = "   that the appropriate bytes of `*ptr` are initialized as defined by that"] # [doc = "   variant's bit validity (although note that the variant may contain another"] # [doc = "   enum type, in which case the same rules apply depending on the state of"] # [doc = "   its discriminant, and so on recursively)."] pub enum AsInitialized { }
    };
}

AsInitialized!();